# learn-lessons-roots.ps1 — python-direct Windows launcher for learn-lessons-roots.py (NO bash re-exec).
# Generated by coordinator/bin/gen-launcher-shim.py — do NOT hand-edit; regenerate.
# 2026-07-19 Windows de-bash campaign. See docs/wiki/windows-cmd-shims.md and
# docs/plans/2026-07-19-debash-coordinator-windows.md.
#
# Resolves a Python interpreter and runs the co-located entrypoint "learn-lessons-roots.py"
# directly. install-substrate.py substitutes __PYTHON_BIN__ with the
# absolute interpreter path resolved at install time (or the empty string when
# none was resolvable). Falls back to `python.exe` on PATH, then `py -3` -- when
# the baked value is empty, still the unsubstituted token, OR names a path that
# is no longer on disk. That last rung (the Test-Path gate below, the PowerShell
# analog of the .cmd ladder's `if exist`) is what makes a `~/.claude` synced
# between a Mac and a Windows box self-healing instead of a permanent hard
# failure: each launcher carries the OTHER platform's interpreter path, and
# falling back on non-existence is the only repair that is correct on whichever
# platform is actually running.
$ErrorActionPreference = 'Stop'
$_here = Split-Path -Parent $MyInvocation.MyCommand.Path
$_entry = Join-Path $_here 'learn-lessons-roots.py'
$_pybin = '__PYTHON_BIN__'
if ($_pybin -eq '__PYTHON_BIN__') { $_pybin = '' }
if ($_pybin -ne '' -and -not (Test-Path -LiteralPath $_pybin)) { $_pybin = '' }
if ($_pybin -ne '') {
    & $_pybin $_entry @args
    exit $LASTEXITCODE
}
$_py = Get-Command python.exe -ErrorAction SilentlyContinue | Where-Object { $_.Source -notmatch '\WindowsApps\' } | Select-Object -First 1
if ($_py) {
    & $_py.Source $_entry @args
    exit $LASTEXITCODE
}
$_pyl = Get-Command py -ErrorAction SilentlyContinue
if ($_pyl) {
    & $_pyl.Source -3 $_entry @args
    exit $LASTEXITCODE
}
[Console]::Error.WriteLine('[learn-lessons-roots] ERROR: no Python interpreter found (python.exe / py -3).')
[Console]::Error.WriteLine('[learn-lessons-roots] Install Python: https://www.python.org/downloads/windows/')
exit 127
